class DataNotAvailable(Exception):
    pass


class DataInconsistent(Exception):
    pass


class IncorrectParameterValue(Exception):
    pass


class NoCellsAvailable(Exception):
    pass


class CellGroupDoesntExist(Exception):
    pass


def raise_value_error(param, value, subpage):
    msg = "Incorrect value of {param} parameter: {value}. " \
          "Please consult the documentation for appropriate value range: " \
          "https://onion.wroclaw.nsn-rdnet.net/branches/master/cli-docs/{subpage}".format(param=param,
                                                                                          value=value,
                                                                                          subpage=subpage)
    raise ValueError(msg)


class ReleaseNotSupported(Exception):
    pass
